import { describe, expect, test } from 'claude-code/testing'
import { checkText, loadLists } from '../hooks/check.ts'
import { EXCEPTIONS, FAMILIARITY, REPLACEMENTS } from '../hooks/data.ts'

// hooks/data.ts is generated by scripts/build_data.py. These tests pin what the checker relies on
// in it: the shape of each list and the choices the script makes, including J07's reviewed allowlist
// (KEEP), read through the checker's real matcher. Each test was shown to fail when the step of the
// script it names is removed (the script was run, changed, into a scratch folder).

const famLines = FAMILIARITY.split('\n')
const fam = famLines.map(line => {
  const tab = line.indexOf('\t')
  return { line, word: line.slice(0, tab), rating: line.slice(tab + 1) }
})
const ratingOf = new Map(fam.map(f => [f.word, Number(f.rating)]))

type Replacement = { from: string; to: string[]; source: string; unless?: string }
const reps = JSON.parse(REPLACEMENTS) as Replacement[]
const rep = (from: string) => reps.find(r => r.from === from)

const exceptions = EXCEPTIONS.split('\n')
const SOURCES = ['plainlanguage.gov', '18F', 'GOV.UK', 'iso-24495']

describe('FAMILIARITY', () => {
  test('every line is one lower-case word: letters, with apostrophes only inside a word', () => {
    const bad = fam.filter(f => !/^\p{L}+(?:'\p{L}+)*$/u.test(f.word) || f.word !== f.word.toLowerCase())
    expect(bad.slice(0, 5).map(f => f.line)).toEqual([])
  })

  test("no form ending in 's is listed (a checker removes a final 's before looking a word up)", () => {
    expect(fam.filter(f => /'s$/.test(f.word)).slice(0, 5).map(f => f.line)).toEqual([])
  })

  test('every rating is between 1.0 and 7.0, with one decimal place', () => {
    const bad = fam.filter(f => !/^[1-7]\.\d$/.test(f.rating) || Number(f.rating) > 7)
    expect(bad.slice(0, 5).map(f => f.line)).toEqual([])
  })

  test('ratings are the precise values, not the whole-number ones', () => {
    // The source has a whole-number column (GPT_Fam_dominant) and a precise one (GPT_Fam_probs).
    const whole = fam.filter(f => f.rating.endsWith('.0')).length
    expect(whole).toBeLessThan(fam.length / 2)
  })

  test('each word is listed once', () => {
    const seen = new Set<string>()
    const twice = fam.filter(f => (seen.has(f.word) ? true : (seen.add(f.word), false)))
    expect(twice.map(f => f.line)).toEqual([])
  })

  test('each word carries its own rating: everyday words at or above the 6.0 cut-off, these terms below it', () => {
    const everyday = ['the', 'house', 'water', 'people', 'because', 'question', 'morning', 'children']
    const terms = ['repo', 'api', 'endpoint']
    expect(everyday.filter(w => !((ratingOf.get(w) ?? 0) >= 6.0))).toEqual([])
    expect(terms.filter(w => !((ratingOf.get(w) ?? 7) < 6.0))).toEqual([])
  })

  test('the whole list was built, not a part of it', () => {
    expect(fam.length).toBeGreaterThan(50_000)
  })
})

describe('REPLACEMENTS', () => {
  test('every entry is { from, to, source, unless? } and nothing else', () => {
    const bad = reps.filter(r => {
      const keys = Object.keys(r).sort().join(',')
      const okKeys = keys === 'from,source,to' || keys === 'from,source,to,unless'
      const okFrom = typeof r.from === 'string' && r.from !== '' && r.from === r.from.toLowerCase().trim()
      const okTo = Array.isArray(r.to) && r.to.every(t => typeof t === 'string' && t.trim() === t && t !== '')
      const okUnless = r.unless === undefined || (typeof r.unless === 'string' && r.unless !== '')
      return !(okKeys && okFrom && okTo && okUnless && typeof r.source === 'string')
    })
    expect(bad.slice(0, 5)).toEqual([])
  })

  test('each word or phrase has one entry', () => {
    const seen = new Set<string>()
    expect(reps.filter(r => (seen.has(r.from) ? true : (seen.add(r.from), false))).map(r => r.from)).toEqual([])
  })

  test("the list is jargone's reviewed allowlist (KEEP in scripts/build_data.py), not the merged sources", () => {
    // The 0.1.0 trial found the 336 merged entries wrong far more often than right (lab branch claude/jargone-lab: 2026-10-31-trial/trial.md),
    // so only the reviewed entries ship. Changing this list means changing KEEP and saying why there.
    expect(reps.map(r => r.from).sort()).toEqual([
      'a large number of', 'a small number of', 'ascertain', 'at the present time', 'at this moment in time',
      'at this point in time', 'commence', 'due to the fact that', 'each and every', 'end result', 'expedite',
      'expend', 'for a period of', 'general consensus', 'has the ability to', 'in an effort to', 'in order that',
      'in order to', 'in regard to', 'in spite of the fact that', 'in the absence of', 'in the event that',
      'in the near future', 'is able to', 'is applicable to', 'make a decision', 'notwithstanding the fact that',
      'numerous', 'prior to', 'pursuant to', 'repeat again', 'revert back', 'subsequent to',
      'take into consideration', 'the majority of', 'until such time as', 'utilise', 'utilize', 'with regard to',
    ])
  })

  test('every swap is a word or phrase to put in: never advice in brackets, never "(omit)", never none', () => {
    expect(reps.filter(r => r.to.length === 0 || r.to.some(t => t.startsWith('('))).map(r => r.from)).toEqual([])
  })

  test('a kept entry offers only the swaps that pass, not every swap its sources give', () => {
    expect(rep('in order to')?.to).toEqual(['to']) // the sources also give "(omit)"
    expect(rep('due to the fact that')?.to).toEqual(['because']) // and "due to", "since"
    expect(rep('at the present time')?.to).toEqual(['now']) // and "at present"
    expect(rep('commence')?.to).toEqual(['start', 'begin'])
    expect(rep('utilize')?.to).toEqual(['use'])
  })

  test("jargone's own note on when to keep the word goes with the two entries that have one wrong sense", () => {
    expect(rep('in order to')?.unless).toContain('"in sequence"')
    expect(rep('prior to')?.unless).toContain('noun')
    expect(reps.filter(r => r.unless !== undefined).map(r => r.from).sort()).toEqual(['in order to', 'prior to'])
  })

  test('an entry names every source that lists it, and each of the four sources is read in its own format', () => {
    expect(rep('in order to')?.source).toBe('plainlanguage.gov, 18F, GOV.UK, iso-24495') // all four parsers
    expect(rep('utilize')?.source).toBe('plainlanguage.gov, 18F, iso-24495') // 18F: the words after "use"
    expect(rep('utilise')?.source).toBe('GOV.UK, iso-24495') // GOV.UK: the words in quotation marks
    expect(rep('numerous')?.source).toBe('plainlanguage.gov') // the plainlanguage.gov table
    expect(rep('revert back')?.source).toBe('iso-24495') // iso-24495 DOUBLETS
    expect(rep('has the ability to')?.source).toBe('iso-24495') // iso-24495 WORDY_PHRASES
  })

  test('only the four chosen sources are used, and each one still contributes (so each credit is still owed)', () => {
    const named = new Set(reps.flatMap(r => r.source.split(', ')))
    expect([...named].sort()).toEqual([...SOURCES].sort())
  })

  test('nothing the trial found harmful ships', () => {
    const trialFound = ['it is', 'there is', 'there are', 'evidenced', 'approximate', 'remain', 'depart', 'land',
      'advance', 'touchpoint', 'identical', 'combined', 'contains', 'caveat', 'progress', 'simple', 'establish',
      'reflect', 'relative to', 'it appears', 'aircraft', 'identify', 'ensure']
    expect(trialFound.filter(f => rep(f) !== undefined)).toEqual([])
  })
})

// The same list through the checker's real matcher. J07 compares words after removing a plural or verb
// ending, so an entry reaches more forms than it names; these pin what the shipped list does there.
describe('REPLACEMENTS through J07', () => {
  const lists = loadLists(FAMILIARITY, REPLACEMENTS, EXCEPTIONS)
  const j07 = (text: string) => checkText({ text, lists, codes: ['J07'] }).findings.filter(f => f.code === 'J07')

  test('every entry is reached: J07 offers its swaps when the text uses it', () => {
    const dead = reps.filter(r => {
      const f = j07(`We note: ${r.from} here.`)
      return !(f.length === 1 && f[0].term?.toLowerCase() === r.from && JSON.stringify(f[0].suggestion) === JSON.stringify(r.to))
    })
    expect(dead.map(r => r.from)).toEqual([])
  })

  test("other forms of a kept word are reached, so the sources' entries for them are not needed", () => {
    const terms = (t: string) => j07(t).map(f => f.term?.toLowerCase())
    expect(terms('They utilized it.')).toEqual(['utilized'])
    expect(terms('We are utilizing it.')).toEqual(['utilizing'])
    expect(terms('We are utilising it.')).toEqual(['utilising'])
    expect(terms('The job commenced.')).toEqual(['commenced'])
    expect(terms('It commences at noon.')).toEqual(['commences'])
    expect(terms('We expedited it.')).toEqual(['expedited'])
  })

  test('the forms the trial found harmful get no swap', () => {
    // Our own sentences, using the forms the trial saw (its records quote private text).
    const text = [
      'The evidence is clear. It is done. There are three files. The remaining tests pass.',
      'This departs from the standard. Land the change today. Book it in advance.',
      'The files are byte-identical. It is a self-contained script. Combine the lists.',
      'One caveat applies. The work is in progress. It is a simple fix. We established the cause.',
      'The scores reflect last year. It is fast relative to disk. It appears twice in the list.',
      'The aircraft is late. Identify the cause. Ensure it runs. The approximate count is ten.',
    ].join('\n\n')
    expect(j07(text).map(f => f.term)).toEqual([])
  })
})

describe('EXCEPTIONS', () => {
  test('one lower-case word per line, each once', () => {
    expect(exceptions.filter(w => !/^[a-z]+$/.test(w))).toEqual([])
    expect(new Set(exceptions).size).toBe(exceptions.length)
  })

  test('the examples the specification and the build brief name are exceptions', () => {
    const named = ['implement', 'execute', 'require', 'deploy', 'commit', 'instance', 'significant', 'interest', 'liability']
    expect(named.filter(w => !exceptions.includes(w))).toEqual([])
  })

  test('words the sources offer a swap for, whose swap would damage technical writing, are exceptions and do not ship', () => {
    const damaging = ['parameters', 'delete', 'function', 'interface', 'address', 'request', 'option', 'type',
      'render', 'validate', 'terminate', 'implement', 'execute', 'require', 'deploy', 'commit', 'utilization']
    expect(damaging.filter(w => !exceptions.includes(w))).toEqual([])
    expect(damaging.filter(w => rep(w) !== undefined)).toEqual([])
  })
})
